"""Build the dataset's generated files from data/rhythms.yaml and data/sources.yaml.

    python scripts/build.py          # write the generated files
    python scripts/build.py --check  # exit 1 if the data is invalid or any generated file is stale

Generated from the two YAML files (never edit these by hand):

- data/rhythms.json: the dataset, embedded in the Rust crate and its Python and WebAssembly bindings;
- data/rhythms.csv: the same records as one table;
- the R claims in claims.yaml, between the "generated" marker comments;
- the measurement tables in README.md, between the rhythms-table markers.

Generated from CITATION.cff:

- .zenodo.json: the metadata Zenodo reads instead of CITATION.cff. Zenodo's importer takes a single
  licence, so the record carries the data licence and a note naming the code licence.

After writing, it runs `ek readme-table claims.yaml README.md --write`, so that the README claims
table follows the regenerated R claims; without the ek CLI it prints that command to run instead.
Needs PyYAML and jsonschema.
"""

from __future__ import annotations

import argparse
import csv
import io
import json
import re
import shutil
import subprocess
import sys
import tomllib
from pathlib import Path
from typing import Any

import yaml
from jsonschema import Draft202012Validator

ROOT = Path(__file__).resolve().parents[1]
RHYTHMS, SOURCES = ROOT / "data" / "rhythms.yaml", ROOT / "data" / "sources.yaml"
JSON_OUT, CSV_OUT = ROOT / "data" / "rhythms.json", ROOT / "data" / "rhythms.csv"
CLAIMS, README = ROOT / "claims.yaml", ROOT / "README.md"
CITATION, ZENODO = ROOT / "CITATION.cff", ROOT / ".zenodo.json"

CLAIMS_START = "  # --- generated by scripts/build.py from data/rhythms.yaml: do not edit by hand ---"
CLAIMS_END = "  # --- end of generated claims ---"
README_START, README_END = "<!-- rhythms-table:start -->", "<!-- rhythms-table:end -->"

# Species: the id prefix and the plain word the description must contain, so values never mix.
SPECIES = {"Homo sapiens": ("HUMAN", "human"), "Mus musculus": ("MOUSE", "mouse")}
TOPICS = {
    "egg-activation": "Egg activation",
    "sperm": "Sperm",
    "oviduct": "Oviduct",
    "uterus": "Uterus",
    "preimplantation": "Preimplantation development",
    "heart": "Embryonic heart",
    "segmentation": "Segmentation clock",
    "genome-activation": "Genome activation",
}
STATISTIC = {"reported": "as reported"}
UNIT_TEXT = {"/min": "per min"}
COUNTABLE = {"cells", "sparks", "vesicles", "atoms"}
FIELDS = (
    "id", "version", "topic", "quantity", "species", "kind", "value", "min", "max", "unit", "statistic",
    "stage", "method", "n", "n_unit", "series", "at", "notes", "contested",
)  # fmt: skip
SOURCE_FIELDS = ("cite", "title", "doi", "pmid")


def load(path: Path) -> Any:
    return yaml.safe_load(path.read_text(encoding="utf-8"))


def schema_errors(doc: Any, name: str, where: str) -> list[str]:
    schema = json.loads((ROOT / "schema" / name).read_text(encoding="utf-8"))
    errors = sorted(
        Draft202012Validator(schema).iter_errors(doc),
        key=lambda e: list(map(str, e.absolute_path)),
    )
    return [
        f"{where}: {'/'.join(map(str, e.absolute_path)) or 'top level'}: {e.message}"
        for e in errors
    ]


def check(doc: dict, sources: dict) -> list[str]:
    """What the schemas cannot check: ids, species, sources, ranges and series."""
    errors, seen, used, series_shape, series_at = [], set(), set(), {}, {}
    for r in doc["rhythms"]:
        rid = r["id"]
        prefix, word = SPECIES[r["species"]]
        if rid in seen:
            errors.append(f"{rid}: duplicate id")
        seen.add(rid)
        if not rid.startswith(f"bio:{prefix}-"):
            errors.append(
                f"{rid}: the id must start with bio:{prefix}- for {r['species']}"
            )
        if word not in r["quantity"].lower():
            errors.append(f"{rid}: the quantity must name the species ('{word}')")
        if "min" in r and r["min"] >= r["max"]:
            errors.append(f"{rid}: min must be less than max")
        for key in r["sources"]:
            used.add(key)
            if key not in sources:
                errors.append(f"{rid}: unknown source '{key}'")
        if name := r.get("series"):
            if name not in doc["series"]:
                errors.append(f"{rid}: unknown series '{name}'")
            shape = (r["species"], r["kind"], r["unit"])
            if series_shape.setdefault(name, shape) != shape:
                errors.append(
                    f"{rid}: every entry of series '{name}' needs the same species, kind and unit"
                )
            if r["at"] in series_at.setdefault(name, set()):
                errors.append(
                    f"{rid}: series '{name}' already has an entry at {r['at']}"
                )
            series_at[name].add(r["at"])
    errors += [
        f"data/sources.yaml: '{key}' is not cited by any entry"
        for key in sorted(set(sources) - used)
    ]
    return errors


def records(doc: dict, sources: dict) -> list[dict]:
    """Every entry with its fields in a fixed order, the default version, and its sources spelled out."""
    out = []
    for r in doc["rhythms"]:
        rec = {k: r.get(k, "1.0.0" if k == "version" else None) for k in FIELDS}
        rec["sources"] = [
            {
                "key": key,
                **{f: sources[key][f] for f in SOURCE_FIELDS if f in sources[key]},
            }
            for key in r["sources"]
        ]
        out.append({k: v for k, v in rec.items() if v is not None})
    return out


def number(x: float) -> str:
    return f"{int(x):,}" if float(x).is_integer() else repr(float(x))


def amount(r: dict) -> str:
    """'10–35 min', '19 Hz', '1 spark': the value or range with its unit."""
    unit = UNIT_TEXT.get(r["unit"], r["unit"])
    if "value" in r:
        if r["value"] == 1 and unit in COUNTABLE:
            unit = unit[:-1]
        return f"{number(r['value'])} {unit}"
    return f"{number(r['min'])}–{number(r['max'])} {unit}"


def sample(r: dict) -> str:
    return f"{r['n']:,} {r['n_unit']}" if "n" in r else ""


def statement(r: dict) -> str:
    n = f"; n = {sample(r)}" if "n" in r else ""
    return f"{r['quantity']}: {amount(r)} ({STATISTIC.get(r['statistic'], r['statistic'])}{n})."


def q(text: str) -> str:
    """A YAML double-quoted scalar (JSON strings are valid YAML)."""
    return json.dumps(text, ensure_ascii=False)


def render_json(recs: list[dict], doc: dict, version: str) -> str:
    out = {
        "schema": doc["schema"],
        "version": version,
        "licence": "CC-BY-NC-4.0",
        "series": doc["series"],
        "rhythms": recs,
    }
    return json.dumps(out, indent=2, ensure_ascii=False) + "\n"


def render_zenodo(cff: dict) -> str:
    """Zenodo metadata from CITATION.cff. Zenodo's CITATION.cff importer reads `license` as one
    string, so the dual licence there fails to load; .zenodo.json takes precedence over it."""
    out = {
        "upload_type": "dataset",
        "title": cff["title"],
        "description": cff["abstract"],
        "creators": [
            {
                "name": f"{a['family-names']}, {a['given-names']}",
                "orcid": a["orcid"].removeprefix("https://orcid.org/"),
            }
            for a in cff["authors"]
        ],
        "license": "cc-by-nc-4.0",
        "keywords": cff["keywords"],
        "notes": (
            "Dual licence: the data (data/, schema/ and the generated files) are under CC BY-NC 4.0 "
            "(LICENSES/CC-BY-NC-4.0.txt); the code is under the PolyForm Noncommercial License 1.0.0 "
            "(LICENSE). Zenodo records one licence, so this record shows the data licence."
        ),
    }
    return json.dumps(out, indent=2, ensure_ascii=False) + "\n"


def render_csv(recs: list[dict]) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow([*FIELDS, "source_keys", *(f"source_{f}s" for f in SOURCE_FIELDS)])
    for r in recs:
        srcs = r["sources"]
        joined = [
            " | ".join(s.get(f, "") for s in srcs) for f in ("key", *SOURCE_FIELDS)
        ]
        writer.writerow([r.get(k, "") for k in FIELDS] + joined)
    return buf.getvalue()


def render_claims(recs: list[dict]) -> str:
    lines = []
    for r in recs:
        value = ", ".join(
            f"{k}: {json.dumps(r[k])}" for k in ("value", "min", "max") if k in r
        )
        notes = " ".join(
            filter(
                None,
                [
                    f"Stage: {r['stage']}.",
                    r.get("notes"),
                    r.get("contested") and f"Contested: {r['contested']}",
                ],
            )
        )
        lines += [
            f"  - id: {r['id']}",
            f"    version: {r['version']}",
            "    level: R",
            f"    statement: {q(statement(r))}",
            f"    value: {{{value}, unit: {q(r['unit'])}}}",
            f"    species: {q(r['species'])}",
            f"    method: {q(r['method'])}",
            "    sources:",
            *(
                "      - {"
                + ", ".join(
                    f"{f}: {q(s[f])}" for f in ("cite", "doi", "pmid") if f in s
                )
                + "}"
                for s in r["sources"]
            ),
            f"    notes: {q(notes)}",
            f"    tags: [{q(r['topic'])}]",
        ]
    return "\n".join(lines)


def cell(text: str) -> str:
    return " ".join(str(text).split()).replace("|", "\\|")


def source_link(s: dict) -> str:
    """'Taylor et al. 1993, Human Reproduction', linked: the citation without volume and pages."""
    short = re.sub(r" [^ ]*\d[^ ]*(?=( \(.*\))?$)", "", s["cite"])
    href = (
        f"https://doi.org/{s['doi']}"
        if "doi" in s
        else f"https://pubmed.ncbi.nlm.nih.gov/{s['pmid']}/"
    )
    return f"[{cell(short)}]({href})"


def render_table(recs: list[dict]) -> str:
    out = []
    for topic, title in TOPICS.items():
        rows = [r for r in recs if r["topic"] == topic]
        if not rows:
            continue
        out += [
            f"### {title}",
            "",
            "| Claim | Measurement | Species | Value | n | Sources |",
            "|---|---|---|---|---|---|",
        ]
        for r in rows:
            value = f"{amount(r)} ({STATISTIC.get(r['statistic'], r['statistic'])})" + (
                " ⚑" if "contested" in r else ""
            )
            srcs = "; ".join(source_link(s) for s in r["sources"])
            out.append(
                f"| `{r['id']}` | {cell(r['quantity'])} | *{r['species']}* | {cell(value)} | {cell(sample(r))} | {srcs} |"
            )
        out.append("")
    contested = [r for r in recs if "contested" in r]
    if contested:
        out += ["⚑ **Contested or revised values**", ""]
        out += [f"- `{r['id']}`: {cell(r['contested'])}" for r in contested]
    return "\n".join(out).rstrip()


def splice(text: str, start: str, end: str, block: str, name: str) -> str:
    i, j = text.find(start), text.find(end)
    if i < 0 or j < i:
        raise SystemExit(f"error: {name} has no {start!r} ... {end!r} block")
    return f"{text[: i + len(start)]}\n{block}\n{text[j:]}"


def outputs() -> dict[Path, str]:
    doc, sources = load(RHYTHMS), load(SOURCES)
    errors = schema_errors(doc, "rhythms.schema.json", "data/rhythms.yaml")
    errors += schema_errors(sources, "sources.schema.json", "data/sources.yaml")
    errors = errors or check(doc, sources)
    if errors:
        raise SystemExit("\n".join(f"error: {e}" for e in errors))
    recs = records(doc, sources)
    version = tomllib.loads((ROOT / "Cargo.toml").read_text(encoding="utf-8"))[
        "package"
    ]["version"]
    claims = CLAIMS.read_text(encoding="utf-8")
    readme = README.read_text(encoding="utf-8")
    return {
        JSON_OUT: render_json(recs, doc, version),
        CSV_OUT: render_csv(recs),
        CLAIMS: splice(
            claims, CLAIMS_START, CLAIMS_END, render_claims(recs), "claims.yaml"
        ),
        README: splice(
            readme, README_START, README_END, render_table(recs), "README.md"
        ),
        ZENODO: render_zenodo(load(CITATION)),
    }


def refresh_claims_table() -> None:
    """Regenerate the README claims table from claims.yaml with ek (CI checks it with --check)."""
    ek = shutil.which("ek") or shutil.which("ek", path=str(Path(sys.executable).parent))
    command = ["readme-table", "claims.yaml", "README.md", "--write"]
    if ek is None:
        print(f"note: ek not found; run: ek {' '.join(command)}")
    else:
        subprocess.run([ek, *command], cwd=ROOT, check=True)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--check", action="store_true", help="fail if a generated file is out of date"
    )
    args = parser.parse_args(argv)
    stale = []
    for path, text in outputs().items():
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current == text:
            continue
        stale.append(path.relative_to(ROOT).as_posix())
        if not args.check:
            path.write_text(text, encoding="utf-8", newline="\n")
    if args.check and stale:
        print(
            f"error: out of date: {', '.join(stale)}; run: python scripts/build.py",
            file=sys.stderr,
        )
        return 1
    print(
        f"{'checked' if args.check else 'wrote'}: {', '.join(stale) or 'everything already up to date'}",
        flush=True,
    )
    if not args.check:
        refresh_claims_table()
    return 0


if __name__ == "__main__":
    sys.exit(main())
